CREATE OR REPLACE FUNCTION check_premature_resolution()
RETURNS TRIGGER AS $ 
BEGIN 
    IF NEW.resstat = 'Resolved' THEN 
        -- Check if the Investigation Intensity Index (III) score is above 75.0
        IF EXISTS (
            SELECT 1 
            FROM investigationdetails id
            WHERE id.invdetreg = NEW.invdetref
            AND (
                id.patrecsc > 75.0 OR 
                id.behansc > 75.0 OR 
                id.netansc > 75.0 OR 
                id.grpbehsc > 75.0 OR 
                id.mktabprob > 75.0
            )
        ) THEN 
            RAISE EXCEPTION 'Premature Resolution Block: Investigation Intensity Index (III) score is above 75.0';
        END IF;
    END IF;
    RETURN NEW;
END;
$ LANGUAGE plpgsql;

CREATE TRIGGER resolution_check
BEFORE UPDATE ON enforcementactions
FOR EACH ROW EXECUTE FUNCTION check_premature_resolution();

